#include <algorithm>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <vector>

void printVector(std::vector<int> values) {
    for (std::size_t i = 0; i < values.size(); ++i) {
        if (i > 0) {
            std::cout << ' ';
        }
        std::cout << values[i];
    }
    std::cout << '\n';
}

int main() {
    std::vector<int> scores = {88, 92, 75, 92, 60};
    std::vector<int> seats(4);

    const int sum = std::accumulate(scores.begin(), scores.end(), 0);
    const double average = std::accumulate(scores.begin(), scores.end(), 0.0) / scores.size();
    std::cout << std::fixed << std::setprecision(2);
    std::cout << sum << ' ' << average << '\n';
    std::cout << std::count(scores.begin(), scores.end(), 92) << '\n';
    std::cout << *std::max_element(scores.begin(), scores.end()) << ' '
              << *std::min_element(scores.begin(), scores.end()) << '\n';

    std::sort(scores.begin(), scores.end());
    printVector(scores);
    std::reverse(scores.begin(), scores.end());
    printVector(scores);

    std::iota(seats.begin(), seats.end(), 101);
    printVector(seats);
    std::fill(seats.begin(), seats.end(), 7);
    printVector(seats);
    return 0;
}
